def unique_jobs(rows):
    seen = set()
    result = []
    for row in rows:
        key = (row['source'], row['source_id']) if row['source_id'] is not None and row['source_id'] != '' else None
        if key is not None:
            if key in seen:
                continue
            seen.add(key)
        # if key is None or empty, always keep (do not deduplicate by source_id None/empty)
        result.append(row)
    return result
